import sys
MOD = 998244353

def matrix_power(base, p):
    if p == 0:
        return identity(len(base))
    if p % 2 == 1:
        temp = matrix_power(base, p - 1)
        return multiply(temp, base)
    half = matrix_power(base, p // 2)
    return multiply(half, half)

def identity(size):
    id_matrix = [[0] * size for _ in range(size)]
    for i in range(size):
        id_matrix[i][i] = 1
    return id_matrix

def multiply(a, b):
    res = [[0] * len(b[0]) for _ in range(len(a))]
    for i in range(len(a)):
        for j in range(len(b[0])):
            for k in range(len(a[0])):
                res[i][j] += (a[i][k] % MOD) * (b[k][j] % MOD)
                res[i][j] %= MOD
    return res

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    L = int(input_data[2])
    R = int(input_data[3])
    delta = R - L

    evenCount = 0
    oddCount = 0
    if delta % 2 == 1:
        half = (delta + 1) // 2
        evenCount = half
        oddCount = half
    else:
        half = delta // 2
        evenCount = half
        oddCount = half
        if L % 2 == 1:
            oddCount += 1
        else:
            evenCount += 1

    transition = [[evenCount, oddCount], [oddCount, evenCount]]
    result = matrix_power(transition, m * n)
    totalWays = result[0][0]
    if (n * m) % 2 == 1:
        totalWays += result[0][1]
    print(totalWays % MOD)

if __name__ == "__main__":
    main()

